23: function makeGuidedFields(){const count=+$('#playerCount').value,container=$('#guidedPlayers');const previous=[...container.querySelectorAll('.guided-player')].map(card=>Object.fromEntries([...card.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])));container.innerHTML=Array.from({length:count},(_,i)=>{const old=previous[i]||{},opts=(list,val,label)=>`<option value="">Random ${label}</option>${list.map(x=>`<option ${val===x?'selected':''}>${esc(x)}</option>`).join('')}`;return `<div class="guided-player"><div class="guided-player-title">PLAYER ${String(i+1).padStart(2,'0')}</div><label>Name<input data-field="name" maxlength="32" placeholder="Random name" value="${esc(old.name||'')}"></label><div class="field-row"><label>Class<select data-field="class">${opts(CLASSES,old.class,'Class')}</select></label><label>Aspect<select data-field="aspect">${opts(ASPECTS,old.aspect,'Aspect')}</select></label></div><div class="field-row"><label>Dream moon<select data-field="moon"><option value="">Random moon</option>${['Prospit','Derse'].map(x=>`<option ${old.moon===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Server<select data-field="server"><option value="">Random server relationship</option><option value="none" ${old.server==='none'?'selected':''}>No server / initial host</option>${Array.from({length:count},(_,j)=>j===i?'':`<option value="${j}" ${old.server===String(j)?'selected':''}>Player ${String(j+1).padStart(2,'0')}</option>`).join('')}</select></label></div></div>`}).join('');}
