29: function overviewHtml(){const entered=session.players.filter(p=>session.entryState[p.id].entered).length,links=session.connections.length;return `<div class="world-banner"><div><div class="eyebrow">SESSION SIGNAL · ${esc(session.settings.tone.toUpperCase())}</div><h3>${esc(session.battlefield.name)}</h3><p>${esc(session.battlefield.notes)}</p></div><div class="world-icon">✳</div></div><div class="metric-grid">${metric('PLAYERS',session.players.length,'human participants')}${metric('ENTRY',`${entered}/${session.players.length}`,'players in the Medium')}${metric('SERVER LINKS',links,links?'acyclic dependencies':'intentionally partitioned network')}${metric('LANDS',session.lands.length,'seven Gates per Land')}</div><div class="overview-grid"><div class="panel"><div class="panel-title"><span>SESSION ROSTER</span><em>SEED ${esc(session.seed)}</em></div><div class="roster-mini">${session.players.map(p=>`<div class="roster-row"><span class="entry-num">${String(p.entryOrder).padStart(2,'0')}</span><b>${esc(p.name)}</b><span>${esc(p.title)}</span><small>${esc(p.dreamMoon)}</small></div>`).join('')}</div></div><div class="panel summary-side"><div class="panel-title"><span>INITIAL CONDITIONS</span><em>${esc(session.settings.difficulty.toUpperCase())}</em></div><p class="note"><b>Mode:</b> ${esc(session.mode)} · <b>Tone:</b> ${esc(session.settings.tone)}<br><b>Complications:</b> ${esc(session.settings.complications)}</p><p class="note">${session.globalEvents.map(esc).join('<br>')||'No added complication enabled.'}</p><div class="land-section"><b>PROTOTYPING TAGS</b><p class="note">${session.battlefield.tags.map(esc).join(' · ')}</p></div><button class="action-button" data-jump="entry">Review entry sequence →</button></div></div><div class="panel"><div class="panel-title"><span>SHARED SESSION THREAD</span><em>GENERATION NOTES</em></div><p class="note">Each player’s prototype contributes persistent descriptive tags to the shared Battlefield. Each Land quest asks Consorts to help ... (line truncated to 2000 chars)
30: function playersHtml(){return `<div class="panel-title"><span>SESSION PLAYERS</span><em>${session.players.length} TITLES · ${esc(session.seed)}</em></div><div class="player-grid">${session.players.map(p=>{const sprite=session.sprites.find(x=>x.id===p.spriteId),land=session.lands.find(x=>x.id===p.landId);return `<article class="player-card"><div class="player-card-top"><span class="entry-num">${String(p.entryOrder).padStart(2,'0')}</span><span class="moon-badge">${esc(p.dreamMoon)}</span></div><h3>${esc(p.name)}</h3><div class="player-title">${esc(p.title)}</div><p class="player-aspect">${esc(p.aspect)} · thematic guide: ${esc(ASPECTS_INFO[p.aspect])}</p><div class="land-section"><b>SERVER / CLIENTS</b><p>${p.serverId?`Server: ${esc(playerBy(p.serverId).name)}`:'Initial host / no server'}${p.clientIds.length?` · Clients: ${p.clientIds.map(id=>esc(playerBy(id).name)).join(', ')}`:''}</p></div><div class="land-section"><b>KERNELSPRITE · ${esc(sprite.prototyping[0].input)}</b><p>${esc(sprite.description)}</p><p><b>Persistent tags:</b> ${sprite.tags.map(esc).join(', ')}.</p><p class="note">Second prototype planned: ${esc(sprite.prototyping[1].input)}. Consequences are descriptive implementation rules.</p></div><div class="land-section"><b>LAND</b><p>${esc(land.name)} · ${esc(land.environment)}</p></div><p class="note">${p.generationLog.map(esc).join(' · ')}</p></article>`}).join('')}</div>`}
31: function networkHtml(){const nodes=session.players.map((p,i)=>{const angle=(Math.PI*2*i/session.players.length)-Math.PI/2,x=50+34*Math.cos(angle),y=50+34*Math.sin(angle);return `<div class="network-node" style="left:${x}%;top:${y}%"><span>${p.entryOrder===1?'INITIAL HOST':`ENTRY ${String(p.entryOrder).padStart(2,'0')}`}</span><b>${esc(p.name)}</b><small>${esc(p.title)}</small></div>`}).join(''),edges=session.connections.map(c=>`${esc(playerBy(c.serverId).name)} → ${esc(playerBy(c.clientId).name)}`).join(' · ')||'No server/client links; the session is partitioned by design.';return `<div class="panel-title"><span>SERVER / CLIENT NETWORK</span><em>${session.connections.length} LINKS</em></div><div class="network-layout"><div class="network-graph">${nodes}<div class="network-center">SBURB<br>SESSION</div></div><aside class="network-aside"><div class="panel"><div class="panel-title"><span>DEPENDENCY ORDER</span><em>ACYCLIC</em></div>${session.entryOrder.map((id,i)=>{const p=playerBy(id);return `<div class="network-order"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(p.name)}</b><small>${p.serverId?`server: ${esc(playerBy(p.serverId).name)}`:'initial host'}</small><label>Server<select data-server="${p.id}"><option value="">No server / host</option>${session.players.filter(x=>x.id!==p.id).map(x=>`<option value="${x.id}" ${p.serverId===x.id?'selected':''}>${esc(x.name)} (entry ${x.entryOrder})</option>`).join('')}</select></label></div>`}).join('')}<button class="action-button" id="networkValidate">Validate & reorder</button><p class="note">Changing links preserves your selected relationships. Cycles are rejected; valid entry order is recalculated.</p></div><div class="panel"><div class="panel-title"><span>READABLE SUMMARY</span><em>SERVER → CLIENT</em></div><p class="note">${edges}</p><p class="note">Servers precede their clients in the generated entry order. Initial host: ${esc(playerBy(session.entryOrder[0]).name)}.</p></div></aside></div>`}
32: function landsHtml(){return `<div class="panel-title"><span>LANDS OF THE MEDIUM</span><em>${session.lands.length} WORLDS · 7 GATES EACH</em></div><div class="land-grid">${session.lands.map(l=>{const p=playerBy(l.ownerId),done=l.gates.filter(g=>g.status==='completed').length,next=l.gates.find(g=>g.status!=='completed');return `<article class="land-card"><div class="land-card-head"><div class="land-owner">${esc(p.name.toUpperCase())} · ${esc(p.title.toUpperCase())}</div><h3>${esc(l.name)}</h3><div class="land-biome">${esc(l.environment)} / ${esc(l.secondaryEnvironment)}</div></div><div class="land-body"><div class="land-section"><b>THE PROBLEM</b><p>${esc(l.problem)} — ${esc(l.cause)}.</p></div><div class="land-section"><b>MAIN QUEST</b><p>${esc(l.quest.main)}</p></div><div class="land-section"><b>CONSORTS · ${esc(l.consorts.species.toUpperCase())}</b><p>${esc(l.consorts.description)} ${esc(l.consorts.understanding)}</p></div><div class="land-section"><b>DENIZEN · ${esc(l.denizen.name.toUpperCase())}</b><p>${esc(l.denizen.archetype)} — ${esc(l.denizen.challenge)}.</p></div></div><div class="land-footer"><div class="gate-dots" title="${done} of 7 gates complete">${l.gates.map(g=>`<span class="gate-dot ${g.status==='completed'?'done':g.status==='unlocked'?'next':''}"></span>`).join('')}</div><span>GATES ${done}/7</span><button class="land-expand" data-expand="${l.id}">DETAILS +</button></div><div class="land-details"><div class="detail-columns"><div class="land-section"><b>QUEST RATIONALE</b><p>${esc(l.quest.rationale)}</p><b>GEOGRAPHY & LANDMARKS</b><p>${esc(l.geography)} Landmarks: ${l.landmarks.map(esc).join(' · ')}.</p><b>CONSORT SOCIETY</b><p>${esc(l.consorts.settlement)}: ${esc(l.consorts.customs)} ${esc(l.consorts.understanding)}</p><b>DENIZEN DOMAIN / OUTCOMES</b><p>${esc(l.denizen.domain)}. ${esc(l.denizen.connection)} ${l.denizen.outcomes.map(esc).join(' · ')}. ${esc(l.denizen.reward)}</p></div><div><div class="land-section"><b>SEVEN GATES · IMPLEMENTATION ROU... (line truncated to 2000 chars)
33: function entryHtml(){return `<div class="panel-title"><span>ENTRY SEQUENCE</span><em>${session.players.filter(p=>session.entryState[p.id].entered).length}/${session.players.length} ENTERED</em></div><div class="entry-layout"><div class="entry-list">${session.entryOrder.map((id,i)=>{const p=playerBy(id),s=session.entryState[id],prior=i===0||session.entryState[session.entryOrder[i-1]].entered,serverReady=!p.serverId||session.entryState[p.serverId].entered,steps=[['machinery','Deploy Cruxtruder, Totem Lathe & Alchemiter'],['sprite','Create Kernelsprite'],['firstPrototype','Complete first prototyping'],['pattern','Obtain artifact pattern'],['dowel','Carve Cruxite Dowel'],['artifact','Create Cruxite artifact'],['entered','Activate artifact and enter']],next=steps.find(([key])=>!s[key]);return `<article class="panel entry-player"><div class="entry-row"><span class="entry-num">${String(i+1).padStart(2,'0')}</span><b>${esc(p.name)}</b><span class="entry-state">${s.entered?'ENTERED':next?`READY: ${esc(next[1])}`:'PLAN COMPLETE'}</span></div><p class="note">${p.serverId?`Server assistance from ${esc(playerBy(p.serverId).name)}.`:'Initial host / no server dependency.'} Meteor countdown: ${esc(s.meteor)}.</p><div class="checklist">${steps.map(([key,label])=>`<div class="check-item ${s[key]?'complete':''}"><span>${s[key]?'✓':'○'}</span>${esc(label)}</div>`).join('')}</div><button class="action-button" data-entry="${id}" ${!next||!prior||!serverReady?'disabled':''}>${next?esc(next[1]):'Entry complete'}</button>${!prior?'<p class="note">Waiting for the previous player in the entry sequence.</p>':''}${!serverReady?'<p class="note">Server must enter before this client can proceed.</p>':''}</article>`}).join('')}</div><aside class="entry-side"><div class="panel"><div class="panel-title"><span>CANON ANCHORS</span><em>ENTRY MACHINERY</em></div><p class="note">The Cruxtruder releases a Cruxite Dowel and starts a meteor countdown; the Totem Lathe carves a pattern; the Alchemiter creates ... (line truncated to 2000 chars)
34: function validationHtml(){const items=validationReport(session),errors=items.filter(x=>x.severity==='error'),warnings=items.filter(x=>x.severity==='warning');const rows=items.map(x=>`<li class="validation-item ${x.severity}"><div><span class="severity-label">${esc(x.severity)}</span><b>${esc(x.record)} · ${esc(x.message)}</b><p>${esc(x.why)}</p></div><span class="repairability ${x.repairable?'repairable':'manual'}">${x.repairable?'Repairable':'Review needed'}</span></li>`).join('');return `<section class="validation-panel" aria-live="polite"><div class="panel-title"><span>LIVE DATA VALIDATION</span><em>${errors.length} ERRORS · ${warnings.length} WARNINGS</em></div><p class="note">Checks session integrity without modifying it. “Repairable” means the app can recalculate the affected record; other issues require review.</p>${items.length?`<ul class="validation-list">${rows}</ul>`:'<p class="validation-good">No errors or warnings. The current session passes all registered checks.</p>'}<button class="action-button" id="validateSession">Refresh validation report</button></section>`}
35: function referenceHtml(){return `<div class="panel-title"><span>MECHANICS REFERENCE</span><em>CANON · INTERPRETATION · IMPLEMENTATION</em></div><div class="reference-grid"><article class="reference-card"><h3>Canon anchors</h3><p>The entry sequence references the Cruxtruder, Totem Lathe, Alchemiter, Kernelsprite, and Cruxite artifact. Prospit and Derse are the two dream moons. Lands, Consorts, Denizens, Gates, prototyping, and server/client assistance are represented as session concepts; this console does not simulate the full story mechanics.</p></article><article class="reference-card"><h3>Interpretations</h3><p>Class and Aspect descriptions are thematic guides, not exhaustive definitions or personality predictions. Land motifs, quest connections, NPC knowledge, and Denizen trials are generated creative material, not definitive canon mechanics.</p></article><article class="reference-card"><h3>Implementation rules</h3><p>Seeded assignment, uniqueness controls, one connected server tree with one initial host, topological entry order, and seven sequential Gate states are application rules. Prototype records identify available, planned, and completed influences; only applied completed influences are active. Meteor times are estimates, not live timers. No combat, economy, or online multiplayer is implemented.</p></article><article class="reference-card"><h3>Data & persistence</h3><p>Validation checks Classpect constraints, the server/client graph and entry order, player-owned Lands and sprites, seven distinct registered Gate locations and route states, prototype statuses, and Consort NPC details. Save stores one local browser copy; Export JSON downloads portable session data. Imported files are validated before activation.</p></article></div>${validationHtml()}`}
36: function render(){if(!session)return;$('#welcome').classList.add('hidden');$('#setup').classList.add('hidden');$('#sessionView').classList.remove('hidden');$('#headerStatus').textContent='SESSION ACTIVE';$('#sessionTitle').textContent=session.name;$('#sessionModeLabel').textContent=`· ${session.mode.toUpperCase()}`;$('#sessionMeta').textContent=`${session.players.length} players · seed ${session.seed} · ${session.settings.difficulty} difficulty`;$('#playerTabCount').textContent=session.players.length;$$('#tabs .tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===activeTab));const views={overview:overviewHtml,players:playersHtml,network:networkHtml,lands:landsHtml,entry:entryHtml,reference:referenceHtml};$('#tabContent').innerHTML=views[activeTab]();}
37: function topoFor(links){const rank=Object.fromEntries(session.entryOrder.map((id,i)=>[id,i])),indegree=Object.fromEntries(session.players.map(p=>[p.id,0])),edges=Object.fromEntries(session.players.map(p=>[p.id,[]]));for(const [client,server] of Object.entries(links)){if(server){if(client===server)throw new Error(`${playerBy(client).name} cannot be their own server.`);if(!Object.hasOwn(indegree,server))throw new Error('A server link references a missing player.');edges[server].push(client);indegree[client]++}}const roots=session.players.filter(p=>!links[p.id]);if(roots.length!==1)throw new Error(`The server network must have exactly one initial host; found ${roots.length}.`);const ready=roots.map(p=>p.id),order=[];while(ready.length){const id=ready.shift();order.push(id);for(const child of edges[id]){if(--indegree[child]===0){ready.push(child);ready.sort((a,b)=>rank[a]-rank[b])}}}if(order.length!==session.players.length)throw new Error('These server links create a dependency cycle or disconnected chain.');return order}
38: function commitNetwork(){try{const links={};session.players.forEach(p=>{const el=$(`[data-server="${p.id}"]`);links[p.id]=el?el.value:(p.serverId||'')});const order=topoFor(links);session.players.forEach(p=>{p.serverId=links[p.id]||null;p.clientIds=[]});session.players.forEach(p=>{if(p.serverId)playerBy(p.serverId).clientIds.push(p.id)});session.connections=session.players.filter(p=>p.serverId).map(p=>({serverId:p.serverId,clientId:p.id}));session.entryOrder=order;session.players.forEach(p=>p.entryOrder=order.indexOf(p.id)+1);render();showToast('Network validated; entry order updated.')}catch(e){showToast(e.message)}}
39: function showWelcome(){session=null;$('#welcome').classList.remove('hidden');$('#setup').classList.add('hidden');$('#sessionView').classList.add('hidden');$('#headerStatus').textContent='NO ACTIVE SESSION'}
40: function openSetup(){session=null;$('#welcome').classList.add('hidden');$('#sessionView').classList.add('hidden');$('#setup').classList.remove('hidden');makeGuidedFields();syncGuidedMode();window.scrollTo({top:0,behavior:'smooth'})}
41: function syncGuidedMode(){$('#guidedCard').classList.toggle('hidden',$('#mode').value!=='guided')}
42: function readSetup(){const seed=$('#seed').value.trim();return{name:$('#sessionName').value.trim(),mode:$('#mode').value,count:$('#playerCount').value,seed,difficulty:$('#difficulty').value,complications:$('#complications').value,tone:$('#tone').value,uniqueClasses:$('#uniqueClasses').checked,uniqueAspects:$('#uniqueAspects').checked,guided:guidedInputs()}}
43: function startSession(event){event?.preventDefault();try{const config=readSetup();if(config.mode==='guided'){const fixedNames=config.guided.map(x=>x.name.trim().toLowerCase()).filter(Boolean);if(new Set(fixedNames).size!==fixedNames.length)throw new Error('Guided player names must be unique.');}session=generate(config);activeTab='overview';render();showToast(`Session generated from seed ${session.seed}.`);window.scrollTo({top:0,behavior:'smooth'})}catch(e){showToast(e.message||'Could not generate this session.')}}
44: function persist(){try{localStorage.setItem('sburb-session-save-v1',JSON.stringify(session));showToast('Session saved in this browser.')}catch(e){showToast('Save failed: browser storage is unavailable or full.')}}
45: function checkImported(value){if(!value||typeof value!=='object'||!Array.isArray(value.players)||!Array.isArray(value.lands)||!Array.isArray(value.sprites)||!value.entryState||!Array.isArray(value.entryOrder))throw new Error('This file is not a complete SBURB session.');const issues=validateSession(value);if(issues.length)throw new Error(`Session validation failed: ${issues.join(' ')}`);value.players.forEach(p=>{p.clientIds=Array.isArray(p.clientIds)?p.clientIds:[];p.generationLog=Array.isArray(p.generationLog)?p.generationLog:[]});value.connections=Array.isArray(value.connections)?value.connections:value.players.filter(p=>p.serverId).map(p=>({serverId:p.serverId,clientId:p.id}));return value}
46: function activateSession(value){session=checkImported(value);activeTab='overview';if($('#importDialog').open)$('#importDialog').close();render();showToast('Session restored.');window.scrollTo({top:0,behavior:'smooth'})}
47: function restoreLocal(){try{const raw=localStorage.getItem('sburb-session-save-v1');if(!raw)throw new Error('No local save found in this browser.');activateSession(JSON.parse(raw))}catch(e){showToast(e.message||'Could not restore the local save.')}}
