// Interactive entry milestone: session-backed, action-clock progression.
function initializeEntryData(s){
 if(!s.gameClock||typeof s.gameClock.minutes!=='number')s.gameClock={minutes:0,log:[]};
 s.gameClock.log=Array.isArray(s.gameClock.log)?s.gameClock.log:[];
 s.entrySelectedId=s.entrySelectedId&&s.players.some(p=>p.id===s.entrySelectedId)?s.entrySelectedId:s.entryOrder[0];
 s.entryState=s.entryState||{};
 s.players.forEach(p=>{const state=s.entryState[p.id]||{};Object.assign(state,{machinery:!!state.machinery,started:!!state.started,cruxtruderOpened:!!state.cruxtruderOpened,dowelRetrieved:!!state.dowelRetrieved,pattern:state.pattern||null,dowelPrepared:!!state.dowelPrepared,artifact:state.artifact||null,entered:!!state.entered,entryTime:state.entryTime??null,actualEntryOrder:state.actualEntryOrder??null,meteorRemaining:typeof state.meteorRemaining==='number'?state.meteorRemaining:null,meteorInitial:typeof state.meteorInitial==='number'?state.meteorInitial:null,failure:state.failure||null,emergencyUsed:!!state.emergencyUsed});s.entryState[p.id]=state;
  const sprite=s.sprites.find(x=>x.id===p.spriteId);if(sprite){sprite.prototypes=Array.isArray(sprite.prototypes)?sprite.prototypes:[];sprite.prototyping=Array.isArray(sprite.prototyping)?sprite.prototyping:[];sprite.prototypes.forEach((proto,i)=>{proto.status=proto.status==='Completed'?'Completed':proto.status==='Planned'?'Planned':'Available';if(state.completedPrototypeInputs?.includes(proto.input))proto.status='Completed'});state.completedPrototypeInputs=Array.isArray(state.completedPrototypeInputs)?state.completedPrototypeInputs:[];state.completedPrototypeInputs.forEach(input=>{const proto=sprite.prototypes.find(x=>x.input===input);if(proto)proto.status='Completed'});}
 });
 s.entryCompletionOrder=Array.isArray(s.entryCompletionOrder)?s.entryCompletionOrder:s.players.filter(p=>s.entryState[p.id].entered).sort((a,b)=>(s.entryState[a.id].entryTime||0)-(s.entryState[b.id].entryTime||0)).map(p=>p.id);
}
function entryClockLabel(minutes){const h=Math.floor(minutes/60),m=minutes%60;return `DAY ${Math.floor(h/24)+1} · ${String(h%24).padStart(2,'0')}:${String(m).padStart(2,'0')}`}
function entryStateFor(id){return session.entryState[id]}
function selectedEntryPlayer(){return playerBy(session.entrySelectedId)||playerBy(session.entryOrder[0])}
function entryEvent(message){session.gameClock.log.push({at:session.gameClock.minutes,message});if(session.gameClock.log.length>80)session.gameClock.log.shift()}
function saveEntryQuietly(){try{localStorage.setItem('sburb-session-save-v1',JSON.stringify(session))}catch(_){}}
function tickEntry(minutes,actorName,action){session.gameClock.minutes+=minutes;session.players.forEach(p=>{const st=entryStateFor(p.id);if(st.meteorRemaining!==null&&!st.entered&&!st.failure){st.meteorRemaining=Math.max(0,st.meteorRemaining-minutes);if(st.meteorRemaining===0){st.failure='meteor-impact-imminent';entryEvent(`${p.name} ran out of time; emergency window opened.`)}}});entryEvent(`${actorName}: ${action} (+${minutes} min)`)}
function doEntryAction(action,value){const p=selectedEntryPlayer();if(!p)return;const s=entryStateFor(p.id);const sprite=session.sprites.find(x=>x.id===p.spriteId);const server=p.serverId?playerBy(p.serverId):null;const fail=m=>{showToast(m);return false};if(s.entered)return fail(`${p.name} has already entered the Medium.`);if(s.failure&&action!=='emergency')return fail('The meteor emergency is active. Stabilize the countdown before continuing.');
 const commit=(cost,label)=>{tickEntry(cost,p.name,label);saveEntryQuietly();render();return true};
 if(action==='begin'){if(p.serverId)return fail('Only the initial host begins locally. Your server must deploy your machinery.');if(s.started)return fail('Your entry sequence has already begun.');s.started=true;s.machinery=true;return commit(2,'began the session; host machinery came online')}
 if(action==='deploy'){const client=playerBy(value),cs=client&&entryStateFor(client.id);if(!client||client.serverId!==p.id)return fail('That player is not your assigned client.');if(!s.entered)return fail('You must enter the Medium before deploying machinery for a client.');if(cs.machinery)return fail(`${client.name} already has deployed machinery.`);cs.machinery=true;cs.started=true;return commit(3,`deployed Cruxtruder, Totem Lathe, and Alchemiter for ${client.name}`)}
 if(!s.machinery)return fail(server?`Waiting for ${server.name} to enter and deploy your machinery.`:'Begin the host entry sequence first.');
 if(action==='inspect'){return commit(1,'inspected the Cruxtruder')}
 if(action==='open'){if(s.cruxtruderOpened)return fail('The Cruxtruder is already open.');s.cruxtruderOpened=true;const duration=45+hashSeed(`${session.seed}:${p.id}:meteor`)%31;s.meteorInitial=duration;s.meteorRemaining=duration;return commit(2,`opened the Cruxtruder; meteor countdown started at ${duration} minutes`)}
 if(action==='retrieve'){if(!s.cruxtruderOpened)return fail('Open the Cruxtruder before retrieving its contents.');if(s.dowelRetrieved)return fail('The Cruxite Dowel is already in your inventory.');s.dowelRetrieved=true;return commit(2,'retrieved the Cruxite Dowel from the Cruxtruder')}
 if(action==='prototype'){const proto=sprite?.prototypes?.[Number(value)];if(!proto)return fail('That prototype slot does not exist.');if(proto.status==='Completed'||s.completedPrototypeInputs.includes(proto.input))return fail('That prototype has already been applied.');if(proto.status!=='Available')return fail('This prototype is planned, not currently available.');proto.status='Completed';proto.selected=true;s.completedPrototypeInputs.push(proto.input);const tag=proto.influences?.[0]||proto.input.toLowerCase().replace(/[^a-z0-9]+/g,'-');sprite.appliedInfluences=[...new Set([...(sprite.appliedInfluences||[]),tag])];sprite.tags=[...new Set([...(sprite.tags||[]),tag])];sprite.description+=` Its presence now carries the unmistakable influence of ${proto.input}.`;sprite.effects=[...(sprite.effects||[]),`Applied prototype: ${proto.input}.`];if(sprite.prototyping?.[Number(value)])sprite.prototyping[Number(value)].completed=true;return commit(4,`prototyped the Kernelsprite with ${proto.input}`)}
 if(action==='choose-pattern'){const patterns=entryPatterns(p,sprite);if(!patterns.includes(value))return fail('Choose one of the displayed artifact patterns.');s.pattern=value;return commit(2,`selected the ${value} artifact pattern`)}
 if(action==='carve'){if(!s.dowelRetrieved)return fail('Retrieve your Cruxite Dowel from the Cruxtruder first.');if(!s.pattern)return fail('Choose an artifact pattern at the Totem Lathe first.');if(s.dowelPrepared)return fail('The dowel is already carved.');s.dowelPrepared=true;return commit(5,`carved the Cruxite Dowel into a ${s.pattern} pattern`)}
 if(action==='alchemize'){if(!s.dowelPrepared||!s.pattern)return fail('The Alchemiter needs a prepared dowel and its matching pattern.');if(s.artifact)return fail('Your Cruxite artifact has already been created.');const name=`${titleCase(s.pattern)} of ${p.aspect}`;s.artifact={name,description:`A faceted Cruxite ${s.pattern}, cut to catch a ${p.aspect.toLowerCase()}-colored gleam. Its surface carries a faint echo of ${sprite?.prototypes?.find(x=>x.status==='Completed')?.input||'the session signal'}.`,symbol:['✦','◈','✧','⬡'][hashSeed(p.id)%4],pattern:s.pattern,createdAt:session.gameClock.minutes+4};return commit(4,`used the Alchemiter to create ${name}`)}
 if(action==='enter'){if(!s.artifact)return fail('Create your Cruxite artifact before attempting entry.');if(!s.cruxtruderOpened||!s.dowelRetrieved||!s.dowelPrepared)return fail('Entry preparations are incomplete: Cruxtruder, dowel, and Totem Lathe steps are required.');if(!sprite?.prototypes?.some(x=>x.status==='Completed'))return fail('Apply at least one prototype to your Kernelsprite before entering.');if(s.meteorRemaining===null)return fail('Open the Cruxtruder to start the meteor countdown first.');if(s.meteorRemaining<=0||s.failure)return fail('The meteor emergency must be stabilized first.');tickEntry(3,p.name,'activated the Cruxite artifact and entered the Medium');s.entered=true;s.entryTime=session.gameClock.minutes;s.actualEntryOrder=session.entryCompletionOrder.length+1;session.entryCompletionOrder.push(p.id);const land=session.lands.find(l=>l.ownerId===p.id);if(land&&land.gates[0])land.gates[0].status='unlocked';saveEntryQuietly();render();showToast(`${p.name} entered the Medium. Their Land is now available.`);return true}
 if(action==='emergency'){if(!s.failure||s.emergencyUsed)return fail('No recoverable meteor emergency is available.');s.failure=null;s.emergencyUsed=true;s.meteorRemaining=20;tickEntry(1,p.name,'triggered an emergency meteor-delay protocol (+20 min)');saveEntryQuietly();render();showToast('Emergency window stabilized for 20 in-game minutes.');return true}
 return fail('Unknown entry action.');
}
function entryPatterns(p,sprite){const proto=sprite?.prototypes?.find(x=>x.status==='Completed')?.input||'signal';return [`${p.aspect.toLowerCase()} sigil`,`${proto.toLowerCase()} crest`,`seven-point star`].map(x=>x.trim())}
function entryStatusText(s){if(s.entered)return 'IN THE MEDIUM';if(s.failure)return 'METEOR EMERGENCY';if(!s.machinery)return 'AWAITING MACHINERY';if(!s.cruxtruderOpened)return 'READY · CRUXTRUDER';if(!s.dowelRetrieved)return 'RETRIEVE DOWEL';if(!s.pattern)return 'TOTEM LATHE';if(!s.dowelPrepared)return 'CARVE DOWEL';if(!s.artifact)return 'ALCHEMITER';return 'READY TO ENTER'}
function entryActionButton(action,label,disabled=false,value=''){return `<button class="action-button" data-game-action="${action}" ${value!==''?`data-value="${esc(value)}"`:''} ${disabled?'disabled':''}>${label}</button>`}
function entryHtml(){const entered=session.players.filter(p=>entryStateFor(p.id).entered).length,p=selectedEntryPlayer(),s=entryStateFor(p.id),sprite=session.sprites.find(x=>x.id===p.spriteId),server=p.serverId?playerBy(p.serverId):null,patterns=entryPatterns(p,sprite),remaining=s.meteorRemaining===null?'NOT STARTED':`${s.meteorRemaining} MIN`,clients=p.clientIds.map(playerBy).filter(Boolean);return `<div class="panel-title"><span>ENTRY SEQUENCE</span><em>${entered}/${session.players.length} ENTERED · ${entryClockLabel(session.gameClock.minutes)}</em></div><div class="entry-game"><div class="entry-select panel"><div class="panel-title"><span>SESSION ROSTER</span><em>SELECT A PLAYER</em></div><div class="entry-roster">${session.entryOrder.map((id,i)=>{const who=playerBy(id),st=entryStateFor(id);return `<button class="entry-roster-button ${who.id===p.id?'selected':''}" data-select-entry="${who.id}"><span class="entry-num">${String(i+1).padStart(2,'0')}</span><span><b>${esc(who.name)}</b><small>${esc(who.title)}</small></span><i class="${st.entered?'entered':st.failure?'danger':''}">${st.entered?'ENTERED':st.failure?'DANGER':st.machinery?'READY':'WAITING'}</i></button>`}).join('')}</div><div class="clock-card"><span>SESSION CLOCK</span><b>${entryClockLabel(session.gameClock.minutes)}</b><small>Advances only when a meaningful action is taken.</small></div></div><div class="entry-main"><div class="panel entry-character"><div class="entry-character-head"><div><div class="eyebrow">${esc(p.title.toUpperCase())}</div><h2>${esc(p.name)}</h2><p>${server?`Client of <b>${esc(server.name)}</b>`:'Initial host'}${clients.length?` · Server for <b>${clients.map(x=>esc(x.name)).join(', ')}</b>`:''}</p></div><div class="entry-status ${s.failure?'danger':s.entered?'entered':''}">${entryStatusText(s)}</div></div><div class="entry-stats"><div><span>METEOR</span><b class="${s.meteorRemaining!==null&&s.meteorRemaining<15?'danger-text':''}">${remaining}</b></div><div><span>STAGE</span><b>${s.entered?'Complete':s.failure?'Emergency':s.artifact?'Activate':s.dowelPrepared?'Alchemiter':s.pattern?'Totem Lathe':s.dowelRetrieved?'Kernelsprite / Lathe':s.cruxtruderOpened?'Retrieve dowel':'Cruxtruder'}</b></div><div><span>PROTOTYPES</span><b>${sprite?.prototypes?.filter(x=>x.status==='Completed').length||0} APPLIED</b></div></div>${s.failure?`<div class="entry-alert">⚠ The meteor countdown expired. Entry is blocked until an emergency delay is triggered. Your progress is preserved.</div>`:''}${s.entered?`<div class="entry-success"><span>✦</span><div><b>TRANSITION COMPLETE · ENTRY #${s.actualEntryOrder}</b><p>${esc(p.name)} crossed at ${entryClockLabel(s.entryTime)}. ${esc(session.lands.find(l=>l.ownerId===p.id)?.name||'Their Land')} is unlocked for future play.</p></div></div>`:''}</div>
 <div class="machinery-grid"><section class="panel machinery-panel"><div class="machine-icon">⏣</div><div class="panel-title"><span>SERVER DEPLOYMENT</span><em>CRUXTRUDER · LATHE · ALCHEMITER</em></div>${!s.machinery?(p.serverId?`<p class="note">Your server, <b>${esc(server.name)}</b>, must enter the Medium and deploy your entry package. You cannot use unavailable machinery.</p>`:`<p class="note">As initial host, begin the session to bring your own entry machinery online.</p>${entryActionButton('begin','Begin host entry',s.entered)}`):`<p class="note">Your machinery is online.${server?` Deployed by ${esc(server.name)}.`:' Host equipment is ready.'}</p>`}${clients.length?`<div class="client-deployments"><b>YOUR ASSIGNED CLIENTS</b>${clients.map(c=>{const cs=entryStateFor(c.id);return `<div class="deployment-row"><span>${esc(c.name)} · ${cs.machinery?'MACHINERY READY':'WAITING'}</span>${!cs.machinery?entryActionButton('deploy','Deploy machinery',!s.entered,c.id):'<small>DEPLOYED</small>'}</div>`}).join('')}</div>`:''}</section>
 <section class="panel machinery-panel"><div class="machine-icon">◉</div><div class="panel-title"><span>CRUXTRUDER</span><em>RELEASE & COUNTDOWN</em></div><p class="note">Inspect the sealed mechanism, then open it. Opening starts your persistent meteor countdown.</p><div class="machine-actions">${entryActionButton('inspect','Inspect',!s.machinery||s.cruxtruderOpened||s.entered)}${entryActionButton('open',s.cruxtruderOpened?'Cruxtruder opened':'Open Cruxtruder',!s.machinery||s.cruxtruderOpened||s.entered)}</div>${s.cruxtruderOpened?`<div class="machine-result">A sharp report. The countdown is active: <b>${s.meteorRemaining} in-game minutes</b>.${!s.dowelRetrieved?`<br>${entryActionButton('retrieve','Retrieve Cruxite Dowel',s.entered)}`:'<br><b>Cruxite Dowel secured.</b>'}</div>`:''}</section>
 <section class="panel machinery-panel sprite-panel"><div class="machine-icon">✧</div><div class="panel-title"><span>KERNELSPRITE</span><em>PROTOTYPING</em></div><p class="sprite-description">${esc(sprite?.description||'Sprite signal unavailable.')}</p><div class="prototype-slots">${(sprite?.prototypes||[]).map((proto,i)=>`<div class="prototype-slot"><div><b>SLOT ${i+1} · ${esc(proto.input)}</b><small>${proto.status==='Completed'?'APPLIED':proto.status==='Planned'?'PLANNED · NOT APPLIED':'AVAILABLE'}</small><p>${esc((proto.influences||[]).join(', '))}${proto.selected?' · selected by player':''}</p></div>${entryActionButton('prototype',proto.status==='Completed'?'Applied':proto.status==='Planned'?'Planned':'Apply prototype',!s.machinery||!s.dowelRetrieved||proto.status!=='Available'||s.entered,String(i))}</div>`).join('')}</div><p class="note">Only selected, completed prototypes affect the Sprite. Planned slots remain inactive unless explicitly supported later.</p></section>
 <section class="panel machinery-panel"><div class="machine-icon">⌁</div><div class="panel-title"><span>TOTEM LATHE</span><em>ARTIFACT PATTERN</em></div><p class="note">Use the retrieved dowel to choose a pattern and carve its totem. The pattern selection and prepared state are stored separately.</p><div class="pattern-options">${patterns.map(pattern=>`<button class="pattern-choice ${s.pattern===pattern?'chosen':''}" data-game-action="choose-pattern" data-value="${esc(pattern)}" ${!s.machinery||!s.dowelRetrieved||s.dowelPrepared||s.entered?'disabled':''}><b>${esc(pattern)}</b><small>${s.pattern===pattern?'SELECTED':'SELECT PATTERN'}</small></button>`).join('')}</div>${s.dowelRetrieved?entryActionButton('carve',s.dowelPrepared?`Dowel carved · ${esc(s.pattern)}`:'Carve dowel on Totem Lathe',!s.pattern||s.dowelPrepared||s.entered):'<p class="machine-lock">Requires Cruxite Dowel from the Cruxtruder.</p>'}</section>
 <section class="panel machinery-panel"><div class="machine-icon">⌬</div><div class="panel-title"><span>ALCHEMITER</span><em>CRUXITE ARTIFACT</em></div><p class="note">The Alchemiter reads the pattern cut into your dowel. No grist or recipe database is needed for this milestone.</p>${s.artifact?`<div class="artifact-card"><span>${esc(s.artifact.symbol)}</span><div><b>${esc(s.artifact.name)}</b><p>${esc(s.artifact.description)}</p><small>CREATED AT ${entryClockLabel(s.artifact.createdAt)}</small></div></div>`:entryActionButton('alchemize','Create Cruxite artifact',!s.machinery||!s.dowelPrepared||!s.pattern||s.entered)}${s.artifact?entryActionButton('enter','Activate artifact · Enter the Medium',!s.machinery||s.entered||!!s.failure||s.meteorRemaining===null):'<p class="machine-lock">Requires a patterned, carved dowel.</p>'}</section></div>
 ${s.machinery&&!s.entered?`<div class="panel next-action-panel"><b>WHAT TO DO NEXT</b><span>${entryNextStep(p,s,sprite)}</span>${s.failure?entryActionButton('emergency','Trigger emergency meteor delay (+20 min)'):''}</div>`:''}
