const sleep = ms => new Promise(r=>setTimeout(r,ms));
(async()=>{
  const page=await fetch('http://127.0.0.1:9222/json/new?http://127.0.0.1:8765/index.html',{method:'PUT'}).then(r=>r.json());
  const ws=new WebSocket(page.webSocketDebuggerUrl); await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});
  let id=0; const pending=new Map(); ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
  const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
  const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(r.result.exceptionDetails.text+' '+JSON.stringify(r.result.exceptionDetails.exception?.description));return r.result.result.value};
  const js=async js=>evaluate(js);
  await call('Runtime.enable'); await call('Page.enable'); await sleep(500);
  console.log('loaded',await js('document.title'));
  await js("document.querySelector('#startBtn').click(); document.querySelector('#playerCount').value='6'; document.querySelector('#playerCount').dispatchEvent(new Event('change',{bubbles:true})); document.querySelector('#seed').value='MILESTONE-SIX'; document.querySelector('#setupForm').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))");
  await sleep(150);
  console.log('generated',await js("({players:document.querySelectorAll('.roster-row').length,title:document.querySelector('#sessionTitle').textContent})"));
  await js("document.querySelector('[data-tab=entry]').click()");
  const roster=await js("[...document.querySelectorAll('[data-select-entry]')].map(x=>x.dataset.selectEntry)");
  const saved=await js("JSON.parse(localStorage.getItem('sburb-session-save-v1')||'null')");
  const order=saved?.entryOrder||roster;
  const read=async()=>js("JSON.parse(localStorage.getItem('sburb-session-save-v1')||'null')");
  const choose=async pid=>js(`document.querySelector('[data-select-entry="${pid}"]').click()`);
  const action=async(name,value)=>{const q=`[data-game-action="${name}"]${value!==undefined?`[data-value="${value}"]`:''}`;const info=await js(`(()=>{const b=document.querySelector('${q}');return b?{disabled:b.disabled,text:b.textContent.trim()}:null})()`);if(!info||info.disabled)throw Error(`Unavailable action ${name} ${value}: ${JSON.stringify(info)}`);await js(`document.querySelector('${q}').click()`)};
  const model=await js("JSON.parse(localStorage.getItem('sburb-session-save-v1')||'null')");
  if(model) throw Error('Newly generated session should not inherit an old save');
  // Initial host cannot deploy clients before entering.
  const root=order[0];await choose(root);
  const depBefore=await js("[...document.querySelectorAll('.deployment-row button')].map(b=>b.disabled)");
  if(depBefore.some(x=>!x))throw Error('Client deployment was available before server entry');
  const finishPrep=async(pid,{open=true,enter=true}={})=>{await choose(pid);await action('inspect');if(open)await action('open');await action('retrieve');await action('prototype','0');const pat=await js("document.querySelector('[data-game-action=choose-pattern]')?.dataset.value");await action('choose-pattern',pat);await action('carve');await action('alchemize');if(enter)await action('enter')};
  await finishPrep(root);
  let state=(await read()).entryState[root];if(!state.entered)throw Error('Host did not enter');
  const full=(await read());
  // Deploy all root clients, then verify the dependency lock is cleared.
  const clients=full.players.filter(p=>p.serverId===root).map(p=>p.id);
  for(const pid of clients){await choose(root);await action('deploy',pid);await choose(pid);if(!(await read()).entryState[pid].machinery)throw Error(`Machinery not deployed for ${pid}`)}
  if(clients.length<3)throw Error('Seed did not generate enough clients to exercise countdown recovery');
  // Start one client's countdown and complete its prep, but hold entry while peers act.
  const endangered=clients[0];await finishPrep(endangered,{enter:false});
  // Other clients advance the shared session clock enough to expire this meteor.
  for(const pid of clients.slice(1,4))await finishPrep(pid);
  let current=await read();
  if(current.entryState[endangered].failure!=='meteor-impact-imminent')throw Error(`Expected countdown expiration, got ${JSON.stringify(current.entryState[endangered])}`);
  await choose(endangered);await action('emergency');await action('enter');
  // Complete any remaining clients, preserving server-before-client dependencies.
  for(const pid of clients.slice(4)){await finishPrep(pid)}
  current=await read();
  const entered=Object.values(current.entryState).filter(x=>x.entered).length;
  if(entered!==6)throw Error(`Expected 6 entered, got ${entered}`);
  if(current.entryState[endangered].emergencyUsed!==true)throw Error('Emergency use did not persist');
  console.log('complete',JSON.stringify({count:current.players.length,entered,clock:current.gameClock.minutes,order:current.entryCompletionOrder,emergency:current.entryState[endangered].meteorInitial,actions:current.gameClock.log.length}));
  // Reload and restore the automatically saved gameplay session.
  await call('Page.reload');await sleep(700);
  const restored=await js("(()=>{const b=document.querySelector('#restoreBtn');if(b)b.click();return document.querySelector('#sessionView').classList.contains('hidden')})()");
  if(restored)throw Error('Saved session did not restore after reload');
  await js("for(const tab of ['overview','players','network','lands','reference'])document.querySelector(`[data-tab=${tab}]`).click()");
  console.log('views ok',await js("document.querySelector('#tabContent').textContent.includes('LIVE DATA VALIDATION')"));
  ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

