 function landsHtml(){return `<div class="panel-title"><span>LANDS OF THE MEDIUM</span><em>${session.lands.length} WORLDS · 7 GATES EACH</em></div><div class="land-grid">${session.lands.map(l=>{const p=playerBy(l.ownerId),done=l.gates.filter(g=>g.status==='completed').length,next=l.gates.find(g=>g.status!=='completed');return `<article class="land-card"><div class="land-card-head"><div class="land-owner">${esc(p.name.toUpperCase())} · ${esc(p.title.toUpperCase())}</div><h3>${esc(l.name)}</h3><div class="land-biome">${esc(l.environment)} / ${esc(l.secondaryEnvironment)}</div></div><div class="land-body"><div class="land-section"><b>THE PROBLEM</b><p>${esc(l.problem)} — ${esc(l.cause)}.</p></div><div class="land-section"><b>MAIN QUEST</b><p>${esc(l.quest.main)}</p></div><div class="land-section"><b>CONSORTS · ${esc(l.consorts.species.toUpperCase())}</b><p>${esc(l.consorts.description)} ${esc(l.consorts.understanding)}</p></div><div class="land-section"><b>DENIZEN · ${esc(l.denizen.name.toUpperCase())}</b><p>${esc(l.denizen.archetype)} — ${esc(l.denizen.challenge)}.</p></div></div><div class="land-footer"><div class="gate-dots" title="${done} of 7 gates complete">${l.gates.map(g=>`<span class="gate-dot ${g.status==='completed'?'done':g.status==='unlocked'?'next':''}"></span>`).join('')}</div><span>GATES ${done}/7</span><button class="land-expand" data-expand="${l.id}">DETAILS +</button></div><div class="land-details"><div class="detail-columns"><div class="land-section"><b>QUEST RATIONALE</b><p>${esc(l.quest.rationale)}</p><b>GEOGRAPHY & LANDMARKS</b><p>${esc(l.geography)} Landmarks: ${l.landmarks.map(esc).join(' · ')}.</p><b>CONSORT SOCIETY</b><p>${esc(l.consorts.settlement)}: ${esc(l.consorts.customs)} ${esc(l.consorts.understanding)}</p><b>DENIZEN DOMAIN / OUTCOMES</b><p>${esc(l.denizen.domain)}. ${esc(l.denizen.connection)} ${l.denizen.outcomes.map(esc).join(' · ')}. ${esc(l.denizen.reward)}</p></div><div><div class="land-section"><b>SEVEN GATES · IMPLEMENTATION ROUTE</b><div class="gate-list">${l.gates.map(g=>`<div class="gate-row"><span class="gate-num">${g.number}</span><span>${esc(g.location)} — ${esc(g.requirement)}; ${esc(g.challenge)}. ${esc(g.destination)}</span><span class="gate-state ${g.status==='completed'?'completed':g.status==='unlocked'?'available':''}">${g.status.toUpperCase()}</span></div>`).join('')}</div></div><div class="land-section"><b>LOCAL NPCs</b><div class="npc-list">${l.consorts.npcs.map(n=>`<div class="npc"><b>${esc(n.name)} · ${esc(n.role)}</b> — ${esc(n.style)}. ${esc(n.knowledge)}. Status: ${esc(n.status)}.</div>`).join('')}</div></div><div class="land-section"><b>BRANCHES / UNDERLINGS / RESOURCES</b><p>${l.quest.branches.map(esc).join(' ')} Enemy themes: ${l.enemies.map(esc).join(', ')}. ${esc(l.resources)}</p></div><div class="land-section"><b>GENERATION RATIONALE</b><p>${esc(l.generationRationale)}</p></div></div></div><button class="action-button gate-action" data-land="${l.id}" ${!session.entryState[p.id].entered||!next?'disabled':''}>${next?(session.entryState[p.id].entered?`Resolve Gate ${next.number}: ${esc(next.challenge)}`:'Enter the Medium to begin Land progression'):'All seven gates complete — Skaian approach reached'}</button></div></article>`}).join('')}</div>`}
 function entryHtml(){return `<div class="panel-title"><span>ENTRY SEQUENCE</span><em>${session.players.filter(p=>session.entryState[p.id].entered).length}/${session.players.length} ENTERED</em></div><div class="entry-layout"><div class="entry-list">${session.entryOrder.map((id,i)=>{const p=playerBy(id),s=session.entryState[id],prior=i===0||session.entryState[session.entryOrder[i-1]].entered,serverReady=!p.serverId||session.entryState[p.serverId].entered,steps=[['machinery','Deploy Cruxtruder, Totem Lathe & Alchemiter'],['sprite','Create Kernelsprite'],['firstPrototype','Complete first prototyping'],['pattern','Obtain artifact pattern'],['dowel','Carve Cruxite Dowel'],['artifact','Create Cruxite artifact'],['entered','Activate artifact and enter']],next=steps.find(([key])=>!s[key]);return `<article class="panel entry-player"><div class="entry-row"><span class="entry-num">${String(i+1).padStart(2,'0')}</span><b>${esc(p.name)}</b><span class="entry-state">${s.entered?'ENTERED':next?`READY: ${esc(next[1])}`:'PLAN COMPLETE'}</span></div><p class="note">${p.serverId?`Server assistance from ${esc(playerBy(p.serverId).name)}.`:'Initial host / no server dependency.'} Meteor countdown: ${esc(s.meteor)}.</p><div class="checklist">${steps.map(([key,label])=>`<div class="check-item ${s[key]?'complete':''}"><span>${s[key]?'✓':'○'}</span>${esc(label)}</div>`).join('')}</div><button class="action-button" data-entry="${id}" ${!next||!prior||!serverReady?'disabled':''}>${next?esc(next[1]):'Entry complete'}</button>${!prior?'<p class="note">Waiting for the previous player in the entry sequence.</p>':''}${!serverReady?'<p class="note">Server must enter before this client can proceed.</p>':''}</article>`}).join('')}</div><aside class="entry-side"><div class="panel"><div class="panel-title"><span>CANON ANCHORS</span><em>ENTRY MACHINERY</em></div><p class="note">The Cruxtruder releases a Cruxite Dowel and starts a meteor countdown; the Totem Lathe carves a pattern; the Alchemiter creates the artifact. Activating the artifact completes entry. This screen tracks a simplified implementation checklist, not a machinery simulation.</p></div><div class="panel"><div class="panel-title"><span>ENTRY RULE</span><em>SERVER DEPENDENCIES</em></div><p class="note">Entry order is topologically valid. The simulation also gates each client's checklist on their server entering. Countdown values are flavor estimates only; no real-time timer runs.</p></div></aside></div>`}
