 function topoFor(links){const rank=Object.fromEntries(session.entryOrder.map((id,i)=>[id,i])),indegree=Object.fromEntries(session.players.map(p=>[p.id,0])),edges=Object.fromEntries(session.players.map(p=>[p.id,[]]));for(const [client,server] of Object.entries(links)){if(server){if(client===server)throw new Error(`${playerBy(client).name} cannot be their own server.`);if(!Object.hasOwn(indegree,server))throw new Error('A server link references a missing player.');edges[server].push(client);indegree[client]++}}const roots=session.players.filter(p=>!links[p.id]);if(roots.length!==1)throw new Error(`The server network must have exactly one initial host; found ${roots.length}.`);const ready=roots.map(p=>p.id),order=[];while(ready.length){const id=ready.shift();order.push(id);for(const child of edges[id]){if(--indegree[child]===0){ready.push(child);ready.sort((a,b)=>rank[a]-rank[b])}}}if(order.length!==session.players.length)throw new Error('These server links create a dependency cycle or disconnected chain.');return order}
