1: // Persistent, player-owned Land exploration for the playable-Lands milestone.
2: function installLandMilestone(api){
3:  'use strict';
4:  const {playerBy,esc,showToast,render}=api;
5:  const getSession=api.getSession;
6:  const saveQuietly=()=>{try{localStorage.setItem('sburb-session-save-v1',JSON.stringify(getSession()))}catch(_){}};
7:  const makeLocations=land=>{
8:   const names=[land.consorts.settlement,'The Ribbon Path','Wayfinder Archive',...land.landmarks,'Supply Cache',`${land.environment} Relay`];
9:   const unique=[];names.forEach(name=>{if(!unique.includes(name))unique.push(name)});
10:   const ids=unique.map((_,i)=>`place-${i}`),indexOfName=name=>unique.indexOf(name);
11:   const locs=unique.map((name,i)=>({id:ids[i],name,description:'',environment:'',connections:[],npcIds:[],objects:[]}));
12:   const connect=(a,b)=>{if(a>=0&&b>=0&&!locs[a].connections.includes(ids[b]))locs[a].connections.push(ids[b]);if(a>=0&&b>=0&&!locs[b].connections.includes(ids[a]))locs[b].connections.push(ids[a])};
13:   const settlement=0,path=indexOfName('The Ribbon Path'),archive=indexOfName('Wayfinder Archive'),firstLandmark=indexOfName(land.landmarks[0]),cache=indexOfName('Supply Cache'),source=indexOfName(`${land.environment} Relay`);
14:   connect(settlement,path);connect(settlement,archive);connect(path,firstLandmark);connect(firstLandmark,cache);connect(firstLandmark,source);
15:   land.landmarks.forEach((_,i)=>{if(i>0)connect(indexOfName(land.landmarks[i-1]),indexOfName(land.landmarks[i]))});
16:   locs.forEach((loc,i)=>{loc.environment=i===settlement?'settlement':i===path?'route':i===archive?'archive':i===cache?'supply site':i===source?'crisis site':i>=firstLandmark&&i<cache?'landmark':land.environment;});
17:   const npcIds=(land.consorts.npcs||[]).map(n=>n.name);
18:   locs[settlement].npcIds=npcIds.slice(0,1);locs[archive].npcIds=npcIds.slice(1,2);locs[path].npcIds=npcIds.slice(2,3);
19:   const objects=[
20:    {id:'notice',at:settlement,name:'The settlement notice board',description:`Woven markers and handwritten notes document how ${land.consorts.customs}. A fresh warning mentions: ${land.problem}.`,kind:'inspect'},
21:    {id:'tracks',at:path,name:'Scored stones beside the path',description:`Repeated drag marks lead toward ${land.landmarks[0]}; tiny ribbons mark the safest way through ${land.environment}.`,kind:'investigate'},
22:    {id:'inscription',at:archive,name:'The route ledger',description:`An old route ledger records the settlement's customs and the cause of the current trouble: ${land.cause}.`,kind:'inspect'},
23:    {id:'mechanism',at:firstLandmark,name:'A weatherworn mechanism',description:`Its failed fittings match the disturbance described by the Consorts. The machine is entangled with ${land.cause}.`,kind:'investigate'},
24:    {id:'cache',at:cache,name:'A sealed component case',description:'A single, intact relay component rests inside, protected from the local weather.',kind:'collect'},
25:    {id:'relay',at:source,name:'The damaged relay',description:`The relay is the immediate source of trouble: ${land.problem}. Its failure is consistent with ${land.cause}.`,kind:'repair'}
26:   ];
27:   locs.forEach(loc=>{loc.description=loc.id===ids[settlement]?`${land.consorts.description} Their settlement sits where ${land.geography}`:loc.id===ids[path]?`A traversable route through ${land.environment} and ${land.secondaryEnvironment}. ${land.geography}`:loc.id===ids[archive]?`A quiet record room maintained by the ${land.consorts.species}; local knowledge is kept alongside route maps.`:loc.id===ids[cache]?'A tucked-away storehouse near the notable landmark, stocked for emergencies.':loc.id===ids[source]?`A hazardous but accessible site connected to the Land's central problem. ${land.cause}.`: `A notable feature of ${land.name}, shaped by ${land.environment} and ${land.secondaryEnvironment}.`;loc.objects=objects.filter(o=>o.at===ids.indexOf(loc.id)).map(({at,...o})=>o)});
28:   return locs;
29:  };
30:  function initializeLandData(s){
31:   if(!s||!Array.isArray(s.lands))return;
32:   if(!s.landSelectedId||!s.players.some(p=>p.id===s.landSelectedId))s.landSelectedId=s.entryOrder?.[0]||s.players[0]?.id;
33:   s.lands.forEach(land=>{
34:    if(!Array.isArray(land.locations)||!land.locations.length)land.locations=makeLocations(land);
35:    const exp=land.exploration&&typeof land.exploration==='object'?land.exploration:{};
36:    const first=land.locations.find(x=>x.environment==='settlement')||land.locations[0];
37:    Object.assign(exp,{currentLocationId:exp.currentLocationId||first?.id||null,knownLocationIds:Array.isArray(exp.knownLocationIds)?exp.knownLocationIds:['place-0','place-1','place-2'].filter(id=>land.locations.some(x=>x.id===id)),completedObjectives:Array.isArray(exp.completedObjectives)?exp.completedObjectives:[],discoveries:Array.isArray(exp.discoveries)?exp.discoveries:[],conversations:exp.conversations&&typeof exp.conversations==='object'?exp.conversations:{},changes:exp.changes&&typeof exp.changes==='object'?exp.changes:{},items:Array.isArray(exp.items)?exp.items:[],problemKnown:!!exp.problemKnown,clueFound:!!exp.clueFound,questResolved:!!exp.questResolved});
38:    if(!land.locations.some(x=>x.id===exp.currentLocationId))exp.currentLocationId=first?.id||land.locations[0]?.id;
39:    if(!exp.knownLocationIds.length&&first)exp.knownLocationIds.push(first.id);
40:    land.exploration=exp;
41:   });
42:  }
43:  const ownerLand=id=>getSession().lands.find(l=>l.ownerId===id);
44:  const locBy=(land,id)=>land.locations.find(x=>x.id===id);
45:  const markObjective=(exp,text)=>{if(!exp.completedObjectives.includes(text))exp.completedObjectives.push(text)};
46:  const discover=(exp,id,text)=>{if(!exp.knownLocationIds.includes(id))exp.knownLocationIds.push(id);if(text&&!exp.discoveries.some(x=>x.id===`location:${id}`))exp.discoveries.push({id:`location:${id}`,text,at:exp.currentLocationId})};
47:  const completeProblemLearning=(land,exp)=>{exp.problemKnown=true;markObjective(exp,'Learn what is disrupting the Land and why.');const landmark=land.locations.find(x=>x.name===land.landmarks[0]);if(landmark)discover(exp,landmark.id,`A route to ${landmark.name} was shared by the Consorts.`)};
48:  function action(id,kind,value){
49:   const s=getSession(),p=playerBy(s.landSelectedId),land=p&&ownerLand(p.id),exp=land?.exploration;
50:   if(!p||!land||!exp)return false;
51:   const entered=!!s.entryState?.[p.id]?.entered;
52:   const fail=text=>{showToast(text);return true};
53:   if(!entered)return fail(`${p.name} must enter the Medium before exploring their Land.`);
54:   if(kind==='travel'){
55:    const here=locBy(land,exp.currentLocationId),dest=locBy(land,value);
56:    if(!here||!dest||!here.connections.includes(dest.id)||!exp.knownLocationIds.includes(dest.id))return fail('That destination is not a known, connected route from here.');
57:    exp.currentLocationId=dest.id;exp.discoveries.push({id:`arrival:${dest.id}:${getSession().gameClock?.minutes||0}`,text:`Arrived at ${dest.name}.`,at:dest.id});saveQuietly();render();showToast(`Arrived at ${dest.name}.`);return true;
58:   }
59:   if(kind==='object'){
60:    const here=locBy(land,exp.currentLocationId),obj=here?.objects.find(x=>x.id===value);
61:    if(!obj)return fail('That object is not present at the current location.');
62:    if(id==='inspect'||id==='investigate'){
63:     const key=`object:${here.id}:${obj.id}`;if(!exp.discoveries.some(x=>x.id===key))exp.discoveries.push({id:key,text:`${obj.name}: ${obj.description}`,at:here.id});
64:     if(obj.id==='notice'||obj.id==='relay'){completeProblemLearning(land,exp)}
65:     if(obj.id==='inscription')completeProblemLearning(land,exp);
66:     if(obj.id==='mechanism'){
67:      if(!exp.problemKnown)return fail('The mechanism is unfamiliar. Ask a Consort what problem the Land is facing first.');
68:      exp.clueFound=true;markObjective(exp,'Investigate the landmark and trace the problem to its source.');
69:      const cache=land.locations.find(x=>x.name==='Supply Cache'),source=land.locations.find(x=>x.name===`${land.environment} Relay`);
70:      if(cache)discover(exp,cache.id,'A Consort points out a supply cache near the landmark.');if(source)discover(exp,source.id,`The mechanism's route leads toward the ${source.name}.`);
71:     }
72:     if(obj.id==='tracks'){const archive=land.locations.find(x=>x.name==='Wayfinder Archive');if(archive)discover(exp,archive.id,'The scored stones point toward an old route archive.')}
73:     saveQuietly();render();showToast(exp.discoveries.some(x=>x.id===`object:${here.id}:${obj.id}`)?`Investigated ${obj.name}. A discovery was recorded.`:`Nothing new is revealed.`);return true;
74:    }
75:    if(id==='collect'){
76:     if(obj.id!=='cache'||!exp.clueFound)return fail('The sealed case is not yet located. Investigate the landmark and learn what the settlement needs.');
77:     if(exp.items.some(x=>x.id==='relay-component'))return fail('The unique relay component has already been collected.');
78:     exp.items.push({id:'relay-component',name:'Resonant relay component',description:`A salvageable fitting for the mechanism tied to ${land.cause}.`,obtainedAt:here.name,obtainedLocationId:here.id,usedAt:null});
79:     markObjective(exp,'Recover the missing component from the supply cache.');saveQuietly();render();showToast('Collected the unique Resonant relay component.');return true;
80:    }
81:    if(id==='repair'){
82:     const item=exp.items.find(x=>x.id==='relay-component');
