 function validationHtml(){const items=validationReport(session),errors=items.filter(x=>x.severity==='error'),warnings=items.filter(x=>x.severity==='warning');const rows=items.map(x=>`<li class="validation-item ${x.severity}"><div><span class="severity-label">${esc(x.severity)}</span><b>${esc(x.record)} · ${esc(x.message)}</b><p>${esc(x.why)}</p></div><span class="repairability ${x.repairable?'repairable':'manual'}">${x.repairable?'Repairable':'Review needed'}</span></li>`).join('');return `<section class="validation-panel" aria-live="polite"><div class="panel-title"><span>LIVE DATA VALIDATION</span><em>${errors.length} ERRORS · ${warnings.length} WARNINGS</em></div><p class="note">Checks session integrity without modifying it. “Repairable” means the app can recalculate the affected record; other issues require review.</p>${items.length?`<ul class="validation-list">${rows}</ul>`:'<p class="validation-good">No errors or warnings. The current session passes all registered checks.</p>'}<button class="action-button" id="validateSession">Refresh validation report</button></section>`}
